      sentence = "Ever since the Gaia Lines—the meridians through which the Earth's spiritual energy flows—had been overrun by a demonic aura a century ago, monsters and misfortune had pervaded the land. Not only have the people been unable to live in peace, but even the flowers and plants no longer thrive, always withered and crestfallen.",
