      ruchang = -1,
      sentence = "Head in the clouds again?",
      voice = 2,
      next = {8}
    },
    [8] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "A lithe hand suddenly appeared before my eyes, and a familiar roseleaf sage scent wafted from the opening of his sleeve, even thicker than previously.",
      next = {9}
    },
    [9] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "This snapped me back to attention, and I turned and gave Shaw a glare.",
      next = {10}
    },
    [10] = {
      beijing = 4998,
      dhead = 103,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Why must you startle me every time you visit?",
      next = {11}
    },
    [11] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Did I startle you? Your face never seems to show it.",
      voice = 2,
      next = {12}
    },
    [12] = {
      beijing = 4998,
      dhead = 112,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Hmph. That's because I trained it not to.",
      next = {13}
    },
    [13] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Yes, of course. Everyone knows that Faerie Maiden $u is a paragon of lofty purity. Her visage is never tainted with joy or anger.",
      voice = 2,
      next = {14}
    },
    [14] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Shaw fired back a rejoinder with an upturned brow and surveyed the surroundings.",
      next = {15}
    },
    [15] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792102,
      role3 = 792202,
      sentence = "Why do I get the feeling... that your courtyard is much more beautiful than the last time I was here?",
      voice = 2,
      next = {16}
    },
    [16] = {
      beijing = 4998,
      dhead = 107,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792102,
      role3 = 792202,
      sentence = "You always come in autumn and winter. You'd never see any flowers that way. It's almost summer now. Naturally, there are plenty in bloom now.",
      next = {17}
    },
    [17] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792102,
      role3 = 792202,
      sentence = "Indeed. You must have taken great pains to raise these fragile things so well.",
      voice = 2,
      next = {18}
    },
    [18] = {
      beijing = 4998,
      dhead = 107,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792102,
      role3 = 792202,
      sentence = "Oh, it's not that bad. Spending time and effort on something one likes isn't exactly a pain.",
      next = {19}
    },
    [19] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "As long as you like something, then you're willing to put in the time and effort?",
      voice = 2,
      next = {20}
    },
    [20] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Shaw's question seemed so out-of-the-blue that I turned my head at him with a puzzled look. What I found was his gaze locked on my face as if trying to confirm something.",
      next = {21}
    },
    [21] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "His stare stirred up a tingling inside me, and I bit my lip.",
      next = {22}
    },
    [22] = {
      beijing = 4998,
      dhead = 112,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "What? ...Are you saying you don't do the same?",
      next = {23}
    },
    [23] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Of course I do the same.",
      voice = 2,
      next = {24}
    },
    [24] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "With that, Shaw withdrew his gaze and cracked a grin.",
      next = {25}
    },
    [25] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "When it comes to things I like, I don't just \"put in a little effort.\" I use my utmost ability and put all that I have on the line to make it mine.",
      voice = 2,
      next = {26}
    },
    [26] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Just like I thought. Too young. Only the youthful and inexperienced would ever utter such resolute words like \"utmost\". I couldn't help but laugh.",
      next = {27}
    },
    [27] = {
      beijing = 4998,
      dhead = 114,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "You should hold a little back for yourself. You've managed to make considerable progress cultivating your Qi. Wouldn't it be a shame to lose it all?",
      next = {28}
    },
    [28] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Win or lose, that's up to me.",
      voice = 2,
      next = {29}
    },
    [29] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "He paused after that and then added:",
      next = {30}
    },
    [30] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "$u... Have I really made considerable progress?",
      voice = 2,
      next = {31}
    },
    [31] = {
      beijing = 4998,
      dhead = 110,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "Of course. Even if you didn't know that you've had several major breakthroughs, you must be able to feel the Yang energy brimming within you, no?",
      next = {32}
    },
    [32] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      sentence = "As a matter of fact... Lately while walking at night, no lone spirits or stray ghosts dare come near me.",
      voice = 2,
      next = {33}
    },
    [33] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "Shaw muttered to himself and handed the tomes he was holding over to me.",
