      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "I've been at a bottleneck in my cultivation for some time, and I've sought guidance from all sorts of sects, both righteous and nefarious, but none of them have been any help. I've been stuck at this plateau.",
      voice = 2,
      next = {36}
    },
    [36] = {
