      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "Ever since I started using your techniques, cultivation... has become extraordinarily simple.",
      voice = 2,
      next = {37}
    },
    [37] = {
      beijing = 4998,
      dhead = 113,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "These Qi techniques are all of my own devising. Besides, what's wrong with cultivation being simple?",
