    },
    [39] = {
      beijing = 4998,
      dhead = 114,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "Just consider this Faerie Maiden a genius of singular talents who has magnanimously decided to help you.",
