      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "Hahaha! This is the first time I've ever heard anyone call themselves a genius!",
      voice = 2,
      next = {41}
    },
    [41] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
