      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "His frank words brought a hint of heat to my cheeks, and I hastily tried to change topics.",
      next = {45}
    },
    [45] = {
      beijing = 4998,
      dhead = 113,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "Alright, now tell me what you've been up to lately.",
      next = {46}
    },
    [46] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "In order to maintain the stability of the Qi field and preserve peace across the land, I have lived as a hermit in the mountains and depended entirely on Shaw for news of the outside world.",
      next = {47}
    },
    [47] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "The people he's met, the monsters he's vanquished, and even the food and drink he's had...",
      next = {48}
    },
    [48] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "From Shaw's engaging descriptions, I could hear, see, and feel the vibrant world I'd missed for so long.",
      next = {49}
    },
    [49] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "But this time as I listened, I suddenly sensed something not quite right.",
      next = {50}
    },
    [50] = {
      beijing = 4998,
      dhead = 105,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      sentence = "...I'm sure this monster rubbed you the wrong way, but why not just eliminate it and move on? Why beat it half to death and then throw it in front of its mortal enemy?",
      next = {51}
    },
    [51] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792201,
      roleanim = 1.1,
      sentence = "Heh. It angered me. Why should I give it the luxury of a quick death?",
      voice = 2,
      next = {52}
    },
    [52] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792201,
      roleanim = 1.1,
      sentence = "Naturally, letting it be mercilessly slaughtered at the hands of its bitter foe was the only way I could blow off steam.",
      voice = 2,
      next = {53}
    },
    [53] = {
      beijing = 4998,
      dhead = 109,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
