      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792201,
      roleanim = 1.1,
      sentence = "Was he imitating the methods of Mystic Crane? As I looked at Shaw's face, I decided to keep the question to myself. I let out a sigh.",
      next = {55}
    },
    [55] = {
      beijing = 4998,
      dhead = 105,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792201,
      roleanim = 1.1,
      sentence = "...The first time I met you, you were such a well-behaved kid.",
      next = {56}
    },
    [56] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792201,
      roleanim = 1.1,
      sentence = "Tch, who are you calling a kid? You think you're that old?",
      voice = 2,
      next = {57}
    },
    [57] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792201,
      roleanim = 1.1,
      sentence = "Anyway, when I met you, I was about the same as I am now. What exactly is it about me that you find childish?",
      voice = 2,
      next = {58}
    },
    [58] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792201,
      roleanim = 1.2,
      sentence = "Shaw took a step forward as he spoke. With his tall, imposing, and fierce stature, as soon as he drew near, there was a mature and manly domineering quality that was difficult to withstand.",
      next = {59}
    },
    [59] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.1,
      sentence = "I found myself shuffling back half a step. Seeing me retreat only encouraged Shaw to take another step forward, as if he found something amusing.",
      next = {60}
    },
    [60] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.2,
      sentence = "The more I backed off, the more he advanced, until I felt my spine bump against a flower stand and there was nowhere to go. I was plunged into a thick aura of roseleaf sage.",
      next = {61}
    },
    [61] = {
      beijing = 4998,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.2,
      sentence = "I glared reflexively at him, but he just flashed a grin at me.",
      next = {62}
    },
    [62] = {
      beijing = 4998,
      dhead = 112,
      dialog = 1,
      music = "30_WarmSnow",
      renming = "$u",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.2,
      sentence = "Having fun?",
