    },
    [64] = {
      beijing = 4998,
      dialog = 2,
      idx = 8,
      male = 8,
      music = "30_WarmSnow",
      renming = "Shaw",
      renwu = "npc",
      role1 = 792000,
      role2 = 792103,
      role3 = 792202,
      roleanim = 1.2,
      sentence = "Seeing the Faerie Maiden $u backpedalling like a fool, too distracted to utter a curse to push me back, it's quite entertain—oof!",
      voice = 2,
      next = {65}
    },
    [65] = {
      beijing = 4998,
